// Surface the next handoff on both home screens without duplicating workflow logic.
export function CollaborationSummary({
  state,
  mobile = false,
  onOpen,
}: {
  state: MobileState;
  mobile?: boolean;
  onOpen: () => void;
}) {
  const task = collaborationTask(state);
  const report = state.reports.find((r) => r.id === collaborationReportId);
  return (
    <button
      className={`co-summary ${mobile ? "is-mobile" : ""}`}
      onClick={onOpen}
    >
      <span className="co-summary-icon">
        <Layers3 size={22} />
      </span>
      <span className="co-summary-copy">
        <small>双端协同 · 校园餐饮风险专题</small>
        <strong>{task.title}</strong>
        <span>
          {state.collaboration.phase === "identified"
            ? "从专业研判到移动决策，串联每一步"
            : `${task.owner}接续处理${report ? ` · 报告 v${report.revision}` : ""} · 状态已同步`}
        </span>
      </span>
      <Badge tone={task.owner === "App 端" ? "purple" : "blue"}>
        {task.owner}
      </Badge>
      <ArrowRight size={18} />
    </button>
  );
}

